  formula: ["Br = \\Rev\\Big[\\textstyle\\sum_{i=1}^{4} W^{\\text{влт}}_d(f\\,2^{\\delta_i/1200}) + 0.7\\sum_{i=1}^{3} W^{\\text{трб}}_d(\\tfrac f2\\,2^{\\delta_i/1200})\\Big]\\ \\text{— валторны и тромбоны октавой ниже; чем громче, тем больше обертонов}"],
